const files=[];for(const compact of [false,true]){const tags=modules.map(m=>`<script type="application/x-isla" data-isla-source="${m.name}" data-encoding="${compact?'lz4-base64':'base64'}" data-bytes="${m.bytes.length}" data-checksum="${checksum(m.bytes)}">\n${(compact?m.packed:m.bytes).toString('base64').match(/.{1,120}/g).join('\n')}\n</script>`).join('\n');const html=template.replace('</body>',tags+'\n</body>');const name=compact?'ISLA-V2.4-Offline-PASTE-SMALL-No-Music.txt':'ISLA-V2.4-Offline.html';fs.writeFileSync(path.join(destination,name),html);if(compact)fs.writeFileSync(path.join(root,'dist/index.html'),html);files.push({name,bytes:Buffer.byteLength(html)});}
fs.writeFileSync(path.join(root,'build-result.json'),JSON.stringify({modules:modules.length,files,compressionRoundTrip:true},null,2));console.log(JSON.stringify({modules:modules.length,files,compressionRoundTrip:true}));
module.exports={pack,unpack};
